const DE = {
 "id": "csd201-cs8-alien-order",
 "title": "Alien dictionary — recover the letter order with Kahn + a PriorityQueue",
 "src": "src",
 "extra": [
  "cham"
 ],
 "main": "KiemTra",
 "javaMin": 8,
 "timeoutMs": 10000,
 "loose": false,
 "lab211": false,
 "release": 8,
 "rules": [],
 "cases": [
  {
   "name": "examples",
   "input": "RUN toc tob oa obb bnc\nRUN z x z\nRUN abc ab\nRUN ab abc\nRUN z x\nRUN ba bc ac cab\n",
   "expected": "RUN toc tob oa obb bnc -> \"acntob\"\nRUN z x z -> \"\"\nRUN abc ab -> \"\"\nRUN ab abc -> \"abc\"\nRUN z x -> \"zx\"\nRUN ba bc ac cab -> \"bac\"\n"
