        t.setDaemon(true);
        t.start();
        try {
            t.join(ms);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        if (t.isAlive()) {
            return label + ": TOO SLOW - not finished after " + ms + " ms (the efficient algorithm needs well under a tenth of that)";
