import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;

public class ArrowGrid {
    static final int[] DR = {0, 0, 1, -1}, DC = {1, -1, 0, 0}; // signs 1 right, 2 left, 3 down, 4 up

    public static int minChanges(int[][] g) {
        int R = g.length, C = g[0].length;
        int[][] d = new int[R][C];
        for (int[] row : d) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }
        Deque<int[]> dq = new ArrayDeque<int[]>();
        d[0][0] = 0;
        dq.add(new int[] {0, 0});
        while (!dq.isEmpty()) {
            int[] p = dq.pollFirst();
            for (int k = 0; k < 4; k++) {
                int x = p[0] + DR[k], y = p[1] + DC[k];
                if (x < 0 || y < 0 || x >= R || y >= C) {
                    continue;
                }
                int w = g[p[0]][p[1]] == k + 1 ? 0 : 1; // follow the arrow = 0, change it = 1
                if (d[p[0]][p[1]] + w < d[x][y]) {
                    d[x][y] = d[p[0]][p[1]] + w;
                    if (w == 0) {
                        dq.addFirst(new int[] {x, y});
                    } else {
                        dq.addLast(new int[] {x, y});
                    }
                }
            }
        }
        return d[R - 1][C - 1];
    }
}

import java.util.*;

// Grader test class (do not edit): one command per input line; after each command it prints the result and the
// state read from the REAL links of your structure (Kiem follows the fields node by node).
public class KiemTra {
    static String[] p;

    static int n(int i) {
        return Integer.parseInt(p[i]);
    }

    static int[] arr(String s) {
        if (s.equals("-")) {
            return new int[0];
        }
        String[] t = s.split(",");
        int[] a = new int[t.length];
        for (int i = 0; i < t.length; i++) {
            a[i] = Integer.parseInt(t[i].trim());
        }
        return a;
    }

    static String str(int[] a) {
        return Arrays.toString(a);
    }

    static String ketQua(String label, int n, String sai) {
        return sai == null ? label + ": all " + n + " agree with the brute force" : label + ": MISMATCH " + sai;
    }

    static int[][] grid(String[] p, int from) {
        int[][] g = new int[p.length - from][];
        for (int i = from; i < p.length; i++) {
            g[i - from] = arr(p[i]);
        }
        return g;
    }

    static int[] DR = {0, 0, 1, -1}, DC = {1, -1, 0, 0};

    static int dijkstra(int[][] g) {
        int R = g.length, C = g[0].length;
        int[] d = new int[R * C];
        Arrays.fill(d, Integer.MAX_VALUE);
        d[0] = 0;
        boolean[] done = new boolean[R * C];
        for (int it = 0; it < R * C; it++) {
            int u = -1;
            for (int v = 0; v < R * C; v++) {
                if (!done[v] && (u == -1 || d[v] < d[u])) {
                    u = v;
                }
            }
            done[u] = true;
            for (int k = 0; k < 4; k++) {
                int x = u / C + DR[k], y = u % C + DC[k];
                if (x < 0 || y < 0 || x >= R || y >= C) {
                    continue;
                }
                int w = g[u / C][u % C] == k + 1 ? 0 : 1;
                d[x * C + y] = Math.min(d[x * C + y], d[u] + w);
            }
        }
        return d[R * C - 1];
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        while (sc.hasNextLine()) {
            String line = sc.nextLine().trim();
            if (line.isEmpty()) {
                continue;
            }
            p = line.split("\\s+");
            String r = "ok";
            try {
                if (p[0].equals("RUN")) {
                    r = String.valueOf(ArrowGrid.minChanges(grid(p, 1)));
                } else if (p[0].equals("RANDOM")) {
                    Random rnd = new Random(123);
                    String sai = null;
                    for (int t = 0; t < 3000 && sai == null; t++) {
                        int R = 1 + rnd.nextInt(6), C = 1 + rnd.nextInt(6);
                        int[][] g = new int[R][C];
                        for (int[] row : g) {
                            for (int i = 0; i < C; i++) {
                                row[i] = 1 + rnd.nextInt(4);
                            }
                        }
                        int got = ArrowGrid.minChanges(g), want = dijkstra(g);
                        if (got != want) {
                            sai = Arrays.deepToString(g) + " -> " + got + ", expected " + want;
                        }
                    }
                    r = ketQua("3000 random arrow grids vs O(V^2) Dijkstra", 3000, sai);
                } else {
                    final int[][] g = new int[1000][1000];
                    Random rnd = new Random(125);
                    for (int[] row : g) {
                        for (int i = 0; i < row.length; i++) {
                            row[i] = 1 + rnd.nextInt(4);
                        }
                    }
                    final int[] got = new int[1];
                    r = Kiem.hen("1000 x 1000 grid", 3000, new Runnable() {
                        public void run() {
                            got[0] = ArrowGrid.minChanges(g);
                        }
                    }) + ", changes " + got[0];
                }
            } catch (RuntimeException e) {
                r = "THROWS " + Kiem.ten(e);
            }
            System.out.println(line + " -> " + r);
        }
    }
}

